/* Donums HR admin console */
body.admin{background:linear-gradient(180deg,#eef2f7 0%,#f7f8fb 100%);font-size:15px;display:flex;min-height:100vh;color:#1e293b}
.a-side{width:256px;flex:none;background:linear-gradient(180deg,#0d1728 0%,#111d2d 100%);color:#dfe9f5;padding:18px 12px 20px;position:sticky;top:0;height:100vh;overflow-y:auto;display:flex;flex-direction:column;z-index:30;box-shadow:inset -1px 0 0 rgba(255,255,255,.05)}
.a-brand{display:flex;align-items:center;gap:10px;padding:8px 10px 18px;color:#fff;font-weight:800;text-decoration:none!important}.a-brand img{height:34px;background:#fff;padding:5px 8px;border-radius:9px}
.a-brand span{letter-spacing:.06em;text-transform:uppercase;font-size:.72rem;opacity:.9}
.a-group{font-size:.68rem;letter-spacing:.15em;text-transform:uppercase;color:#99a9b9;padding:16px 10px 8px;font-weight:800}
.a-link{display:flex;gap:10px;align-items:center;padding:10px 12px;border-radius:10px;color:#dfeaf7;font-weight:600;font-size:.9rem;transition:all .15s ease}.a-link:hover{background:rgba(255,255,255,.05);color:#fff;text-decoration:none}
.a-link.on{background:linear-gradient(135deg,rgba(202,167,106,.16),rgba(255,255,255,.04));border:1px solid rgba(202,167,106,.18);color:#fff}
.a-foot{margin-top:auto;padding-top:18px;border-top:1px solid rgba(255,255,255,.08)}
.a-main{flex:1;min-width:0}.a-top{display:flex;align-items:center;gap:14px;padding:16px 26px;background:rgba(255,255,255,.82);backdrop-filter:blur(12px);border-bottom:1px solid rgba(15,23,42,.08);position:sticky;top:0;z-index:20}
.a-top h1{font-size:1.5rem;letter-spacing:-.02em;margin:0}.a-top-r{margin-left:auto;display:flex;align-items:center;gap:10px}
.a-menu{display:none;background:none;border:1px solid var(--line);border-radius:9px;width:40px;height:40px;cursor:pointer;color:var(--ink)}.a-bell{position:relative;color:var(--ink);padding:8px}
.a-body{padding:24px 26px 60px;max-width:1500px}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:22px}
.stat{background:linear-gradient(180deg,#ffffff,#f9fafc);border:1px solid #e5ebf4;border-radius:16px;padding:16px 18px;display:block;color:inherit;box-shadow:0 10px 24px rgba(15,23,42,.04)}a.stat:hover{text-decoration:none;border-color:rgba(202,167,106,.45);transform:translateY(-1px)}.stat b{display:block;font-size:1.6rem;letter-spacing:-.04em;margin-top:8px}.stat small{color:var(--muted)}
.panel{background:linear-gradient(180deg,#fff,#fafcff);border:1px solid #e9edf5;border-radius:18px;margin-bottom:20px;box-shadow:0 10px 24px rgba(15,23,42,.03)}.panel>h2,.panel-h{font-size:1rem;margin:0;padding:16px 18px;border-bottom:1px solid #edf2f7;display:flex;align-items:center;justify-content:space-between;gap:10px}.panel-body{padding:18px}
.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px}.toolbar input[type=search],.toolbar select{width:auto;min-width:170px;padding:10px 12px;border:1px solid #dfe7f0;border-radius:10px;background:#fff}.toolbar .grow{flex:1}
.ck{display:inline-flex;gap:6px;align-items:center}.health{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid #edf2f7;font-size:.9rem}.health:last-child{border:0}.health .ic{margin-top:2px}
.two{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:20px;align-items:start}.two-eq{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}
.kanban{display:flex;gap:12px;overflow-x:auto;padding-bottom:14px;align-items:flex-start}.kcol{flex:0 0 250px;min-height:260px;background:#edf3f8;border:1px solid #dde7f0;border-radius:14px;padding:10px}.kcol h3{font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;color:#5f7486;margin:0 0 10px;padding:6px 8px}
.kcard{background:#fff;border:1px solid #e8edf5;border-radius:12px;padding:12px;margin-bottom:9px;cursor:grab;display:block;color:inherit;font-size:.88rem;box-shadow:0 8px 18px rgba(15,23,42,.03)}.kcard:hover{text-decoration:none;border-color:rgba(202,167,106,.45)}
.tbl-actions{display:flex;gap:6px;flex-wrap:wrap}.rowbtn{background:none;border:1px solid var(--line);border-radius:8px;padding:5px 10px;font:600 .78rem/1.4 var(--font);color:var(--ink);cursor:pointer}
.builder-mod{background:#fff;border:1px solid #edf2f7;border-radius:14px;margin-bottom:14px}.builder-mod>.bm-h{display:flex;gap:10px;align-items:center;padding:12px 16px;background:#f8fafc;border-bottom:1px solid #edf2f7}
.mail{display:grid;grid-template-columns:210px 360px minmax(0,1fr);gap:0;background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;height:calc(100vh - 150px);min-height:520px;box-shadow:0 12px 28px rgba(15,23,42,.04)}
.m-side{border-right:1px solid var(--line);padding:14px 10px;overflow-y:auto;background:#f9fafb}.m-side .btn{width:100%;margin-bottom:14px}.m-box{display:block;padding:7px 10px;font-weight:700;font-size:.9rem;color:var(--ink)}
.m-f{display:flex;justify-content:space-between;align-items:center;padding:8px 10px;border-radius:9px;color:var(--ink);font-weight:600;font-size:.9rem}.m-f:hover{background:#eef4ff;text-decoration:none}.m-list{border-right:1px solid var(--line);overflow-y:auto;display:flex;flex-direction:column}.m-search{padding:10px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#fff;z-index:1}.m-item{display:block;padding:11px 14px;border-bottom:1px solid #edf2f7;color:inherit}.m-item:hover{background:#f8fafc;text-decoration:none}.m-item.on{background:#f1f5fb}.m-item.unread .s{font-weight:800}
.m-read{overflow-y:auto;padding:0}.m-head{padding:18px 22px;border-bottom:1px solid var(--line)}.m-head h2{font-size:1.25rem;margin:0 0 8px}.m-body{padding:18px 22px}.m-body iframe{width:100%;border:0}
.composer{display:grid;gap:12px}.rte{border:1.5px solid var(--line);border-radius:10px;overflow:hidden;background:#fff}.rte-bar{display:flex;gap:2px;padding:6px;border-bottom:1px solid var(--line);background:#f9fafb}.rte-area{min-height:260px;padding:14px;outline:none;line-height:1.6}.chip-in{display:flex;flex-wrap:wrap;gap:6px}.drop{border:2px dashed #c5d2e1;border-radius:12px;padding:14px;text-align:center;background:#fafcff}
@media(max-width:1100px){.mail{grid-template-columns:190px 1fr;height:auto}.m-read{grid-column:1/3;border-top:1px solid var(--line)}.m-list{max-height:420px}.two,.two-eq{grid-template-columns:1fr}[...]}
@media(max-width:860px){.a-side{position:fixed;left:0;top:0;transform:translateX(-100%);transition:.2s}.a-side.open{transform:none}.a-menu{display:block}.a-body{padding:16px 14px 50px}.a-top{padding:14px 16px}.a-top h1{font-size:1.2rem}}
